// proof.json is generated by scripts/gen_proof_data.mjs from the newest kernel baseline snapshot (lib/site-data/source/BASELINE_<date>.json,
// re-exported weekly by scripts/reexport_proof_feed.mjs). Each row carries its own source file, source row and measured date, so nothing is
// overlaid from lib/ledger.json any more: the old overlay stamped 24 hour fleet readings with the ledger's 2026-10-09 date and made every
// fleet tile read UNKNOWN. EV6: a row measured more than 30 days before the build renders as UNKNOWN (last measured <date>), never the old number.
import raw from "./proof.json";
import { markStale } from "./markStale.mjs";

const TODAY = process.env.PROOF_TODAY || new Date().toISOString().slice(0, 10);
type Stamped<T> = T & { stale?: boolean; lastMeasured?: string; staleReason?: string };

const live = raw;

export const proof = {
  ...live,
  headline: markStale([live.headline], TODAY)[0] as Stamped<typeof live.headline>,
  fleetCost: markStale([live.fleetCost], TODAY)[0] as Stamped<typeof live.fleetCost>,
  charts: markStale(live.charts, TODAY) as Stamped<(typeof live.charts)[number]>[],
  stars: markStale(live.stars, TODAY) as Stamped<(typeof live.stars)[number]>[],
};
